// Fake identity provider for the tests (I0): an ES256 key pair generated by `jose`, a JWKS served by
// `node:http` on 127.0.0.1 (the reads are counted: "unknown kid → a single re-read"), and access tokens
// signed the way Keycloak issues them (typ at+jwt, iss, aud, resource_access.eupadev-api.roles, email, name), each
// field overridable to forge a faulty token.
import { createHash, randomBytes } from 'node:crypto';
import http from 'node:http';
import { once } from 'node:events';
import type { AddressInfo } from 'node:net';
import { exportJWK, generateKeyPair, SignJWT, type CryptoKey, type JWK } from 'jose';
import type { Hat } from '../../src/auth.ts';

export const TEST_ISSUER = 'https://auth.example.test/realms/eupadev';
export const AUDIENCE_TEST = 'eupadev-api';

export interface Account { subject: string; mail?: string | null; name?: string; roles?: readonly Hat[] }
export interface TokenOptions {
  /** `aud` (default: eupadev-api; null = missing). */
  audience?: string | string[] | null;
  /** `iss` (default: TEST_ISSUER). */
  issuer?: string;
  /** `typ` header (default: at+jwt; null = missing). */
  typ?: string | null;
  /** Signing key (default: the published key) and its `kid`. */
  key?: { private: CryptoKey; kid: string };
  /** Claims added as they are (e.g. `cnf`, `realm_access`). */
  claims?: Record<string, unknown>;
  /** Lifetime (default 5 min); '-1m' = already expired. */
  expire?: string;
}

/** Chat step 2: the web client (confidential) as the engine's tests configure it. */
export const CLIENT_WEB_TEST = 'eupadev-web';
export const WEB_TEST_PASSWORD = 'web-client-password-for-tests';

export interface FakeOidc {
  jwksUrl: string;
  /** Number of JWKS reads since the start. */
  reads: () => number;
  token: (account: Account, options?: TokenOptions) => Promise<string>;
  /** New key pair, NOT published (token with an unknown `kid`). */
  unknownKey: () => Promise<{ private: CryptoKey; kid: string }>;
  /**
   * Chat step 2: what Keycloak does when `account` signs in on the authorization URL the engine built — remembers a code
   * bound to its PKCE challenge, nonce and redirect URI, and renders the callback URL (`redirect_uri?code&state`). The
   * token endpoint then checks the code verifier (S256), the redirect URI and the client password (`client_secret_post`).
   */
  authorize: (authorizationUrl: string, account: Account) => URL;
  stop: () => Promise<void>;
}

export async function startFakeOidc(): Promise<FakeOidc> {
  const { publicKey, privateKey } = await generateKeyPair('ES256', { extractable: true });
  // ID tokens: RS256, Keycloak's default for a client (openid-client expects it); its signature is not what the engine trusts (the access token is).
  const { privateKey: idTokenKey } = await generateKeyPair('RS256');
  const jwk: JWK = { ...(await exportJWK(publicKey)), kid: 'test-key-1', use: 'sig', alg: 'ES256' };
  let reads = 0;
  const codes = new Map<string, { account: Account; nonce: string; challenge: string; redirectUri: string; clientId: string }>();
  const readBody = async (req: http.IncomingMessage) => { let t = ''; for await (const m of req) t += (m as Buffer).toString('utf8'); return t; };
  const server = http.createServer((req, res) => {
    void (async () => {
      if (req.method === 'POST' && req.url?.endsWith('/protocol/openid-connect/token')) {
        const p = new URLSearchParams(await readBody(req));
        const c = codes.get(p.get('code') ?? '');
        const challenge = createHash('sha256').update(p.get('code_verifier') ?? '').digest('base64url');
        const ok = c !== undefined && p.get('grant_type') === 'authorization_code' && p.get('redirect_uri') === c.redirectUri && challenge === c.challenge
          && p.get('client_id') === c.clientId && c.clientId === CLIENT_WEB_TEST && p.get('client_secret') === WEB_TEST_PASSWORD;
        if (!ok) {
          console.log(`fake IdP: token request refused (code known: ${c !== undefined}, grant: ${p.get('grant_type')}, redirect_uri ok: ${p.get('redirect_uri') === c?.redirectUri}, pkce ok: ${challenge === c?.challenge}, client ok: ${p.get('client_id') === CLIENT_WEB_TEST && p.get('client_secret') === WEB_TEST_PASSWORD})`);
          res.writeHead(400, { 'Content-Type': 'application/json' });
          return res.end(JSON.stringify({ error: 'invalid_grant' }));
        }
        codes.delete(p.get('code')!);
        const idToken = await new SignJWT({ nonce: c.nonce, azp: c.clientId }).setProtectedHeader({ alg: 'RS256', kid: 'id-token-key' })
          .setSubject(c.account.subject).setIssuer(TEST_ISSUER).setAudience(c.clientId).setIssuedAt().setExpirationTime('5m').sign(idTokenKey);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ access_token: await token(c.account), id_token: idToken, token_type: 'Bearer', expires_in: 300 }));
      }
      reads += 1;
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ keys: [jwk] }));
    })();
  }).listen(0, '127.0.0.1');
  await once(server, 'listening');
  const jwksUrl = `http://127.0.0.1:${(server.address() as AddressInfo).port}/realms/eupadev/protocol/openid-connect/certs`;
  async function token(account: Account, o: TokenOptions = {}): Promise<string> {
    const key = o.key ?? { private: privateKey, kid: 'test-key-1' };
    const header: Record<string, string> = { alg: 'ES256', kid: key.kid };
    if (o.typ !== null) header['typ'] = o.typ ?? 'at+jwt';
    const s = new SignJWT({
      ...(account.mail === null ? {} : { email: account.mail ?? `${account.subject}@example.test` }),
      name: account.name ?? account.subject,
      resource_access: { [AUDIENCE_TEST]: { roles: [...(account.roles ?? [])] } },
      ...(o.claims ?? {}),
    })
      .setProtectedHeader(header as { alg: string })
      .setSubject(account.subject)
      .setIssuer(o.issuer ?? TEST_ISSUER)
      .setIssuedAt()
      .setExpirationTime(o.expire ?? '5m');
    if (o.audience !== null) s.setAudience(o.audience ?? AUDIENCE_TEST);
    return s.sign(key.private);
  }
  return {
    jwksUrl,
    reads: () => reads,
    token,
    async unknownKey() {
      const other = await generateKeyPair('ES256', { extractable: true });
      return { private: other.privateKey, kid: `unknown-key-${Date.now()}` };
    },
    authorize(authorizationUrl, account) {
      const u = new URL(authorizationUrl);
      const q = u.searchParams;
      if (u.href.split('?')[0] !== `${TEST_ISSUER}/protocol/openid-connect/auth` || q.get('response_type') !== 'code' || q.get('code_challenge_method') !== 'S256') throw new Error(`authorization URL unexpected: ${u.href}`);
      const code = randomBytes(16).toString('base64url');
      codes.set(code, { account, nonce: q.get('nonce') ?? '', challenge: q.get('code_challenge') ?? '', redirectUri: q.get('redirect_uri') ?? '', clientId: q.get('client_id') ?? '' });
      const back = new URL(q.get('redirect_uri') ?? '');
      back.searchParams.set('code', code);
      back.searchParams.set('state', q.get('state') ?? '');
      return back;
    },
    stop: () => new Promise((r) => server.close(() => r())),
  };
}
